      "explanation": "The coordination number is defined as the number of Ï-donor atoms that are directly bonded to the central metal atom in a complex."
    },
    {
      "question": "In the complex ion [Fe(CN)6]4-, what is the coordination number?",
      "options": [
        "1",
        "4",
        "6",
        "12"
      ],
      "correct_answer": "6",
      "explanation": "The coordination number for [Fe(CN)6]4- is 6, as there are six cyanide (CN-) ligands bonded to the central iron (Fe) ion."
    },
    {
      "question": "According to IUPAC nomenclature, how should ligands be listed?",
      "options": [
        "By size, from smallest to largest",
        "In order of their charge, from positive to negative",
        "Alphabetically",
        "By the order in which they are written in the formula"
      ],
      "correct_answer": "Alphabetically",
      "explanation": "IUPAC rules dictate that ligands in a coordination complex should be listed in alphabetical order."
    },
    {
      "question": "How are anionic ligands named according to IUPAC rules when they are part of a coordination complex?",
      "options": [
        "Their name remains unchanged",
        "Their anionic ending is replaced with '-ate'",
        "Their anionic ending is replaced with '-o'",
        "They are given a prefix indicating their charge"
      ],
      "correct_answer": "Their anionic ending is replaced with '-o'",
      "explanation": "Anionic ligands are named by replacing their usual anionic ending (like -ide) with the suffix '-o'."
    }
  ]
}

