      "question": "How is the equivalent resistance calculated for resistors in series?",
      "options": [
        "1/R_eq = 1/R1 + 1/R2",
        "R_eq = R1 + R2",
        "R_eq = (R1 * R2) / (R1 + R2)",
        "R_eq = R1 - R2"
      ],
      "correct_answer": "R_eq = R1 + R2",
      "explanation": "For resistors connected in series, the equivalent resistance is the sum of the individual resistances."
    },
    {
      "question": "According to Kirchhoff's junction rule, what is the relationship between incoming and outgoing currents at a junction?",
      "options": [
        "Sum of I_in > Sum of I_out",
        "Sum of I_in < Sum of I_out",
        "Sum of I_in = Sum of I_out",
        "Sum of I_in = 0"
