{
  "title": "Fundamentals of Electrical Circuits",
  "questions": [
    {
      "question": "According to Ohm's law, what is the relationship between voltage (V), current (I), and resistance (R)?",
      "options": [
        "V = I / R",
        "V = I * R",
        "V = R / I",
        "V = I + R"
      ],
      "correct_answer": "V = I * R",
      "explanation": "Ohm's law states that the voltage across a conductor is equal to the product of the current flowing through it and its resistance."
    },
    {
      "question": "Which formula correctly represents the equivalent resistance (R_eq) for two resistors connected in series?",
      "options": [
        "R_eq = R1 * R2",
        "R_eq = R1 / R2",
        "R_eq = R1 + R2",
        "R_eq = 1/R1 + 1/R2"
      ],
      "correct_answer": "R_eq = R1 + R2",
      "explanation": "In a series circuit, the total resistance is the sum of the individual resistances."
    },
    {
      "question": "What does Kirchhoff's junction rule state?",
      "options": [
        "The sum of currents entering a junction equals the sum of currents leaving it.",
        "The sum of voltages in a loop is zero.",
        "Current is inversely proportional to resistance.",
        "Drift velocity is constant regardless of current."
      ],
      "correct_answer": "The sum of currents entering a junction equals the sum of currents leaving it.",
      "explanation": "Kirchhoff's junction rule is based on the conservation of charge, requiring that the total current entering a junction must equal the total current exiting it."
    },
    {
      "question": "Which expression relates current (I) to drift velocity (v_d)?",
      "options": [
        "I = n / (eAv_d)",
        "I = neAv_d",
        "I = v_d / (neA)",
        "I = e / (nAv_d)"
      ],
      "correct_answer": "I = neAv_d",
      "explanation": "The current in a conductor is defined by the product of charge carrier density (n), elementary charge (e), cross-sectional area (A), and drift velocity (v_d)."
    }
  ]
}

